SELECT COUNT(*) FROM
tb_shoptb_blog
WHERE id=#{targetId}

SELECT f.target_id,f.kind,f.created_at,(t.id IS NOT NULL) AS available,t.images,
t.name AS title,t.area,t.avg_price t.title,'' AS area,NULL AS avg_price
FROM tb_user_favorite f LEFT JOIN tb_shoptb_blog t ON t.id=f.target_id WHERE f.user_id=#{userId} AND f.kind=#{kind} ORDER BY f.created_at DESC,f.id DESC LIMIT #{limit} OFFSET #{offset}
